SELECT e.*,s.q1,s.q3,s.q3-s.q1 iqr,s.peer_group_size, CASE WHEN e.unit_price_recomputed < s.q1-{{IQR_MULTIPLIER}}*(s.q3-s.q1) OR e.unit_price_recomputed > s.q3+{{IQR_MULTIPLIER}}*(s.q3-s.q1) THEN TRUE ELSE FALSE END is_anomalous_price, CASE WHEN e.unit_price_recomputed < s.q1-{{IQR_MULTIPLIER}}*(s.q3-s.q1) OR e.unit_price_recomputed > s.q3+{{IQR_MULTIPLIER}}*(s.q3-s.q1) THEN 'POTENTIAL_UNIT_PRICE_ANOMALY_IQR' ELSE NULL END anomaly_reason FROM enriched e JOIN iqr_stats s ON e.year=s.year AND e.buyer_name=s.buyer_name AND e.product_category=s.product_category
